def solve(head):
    if isinstance(head, list) or head is None:
        values = head or []
        out = []; total = 0; active = False
        for value in values + [0]:
            if value == 0:
                if active: out.append(total)
                total = 0; active = False
            else: total += value; active = True
        return out or None
    from quorem_types import ListNode
    values = []
    while head: values.append(head.val); head = head.next
    values = solve(values) or []
    dummy = ListNode(); tail = dummy
    for value in values: tail.next = ListNode(value); tail = tail.next
    return dummy.next
class Solution:
    def segmentSums(self, head):
        return solve(head)

